-- RD-95: "?" em todos os campos do formulário de Financiamento (Novo/Editar contrato).
-- Auditoria auditor_pdca_2 18/11 (jornada/cálculo VERDE; gap = formulário sem "?"). O componente
-- src/components/financiamento/FinanciamentoFormModal.tsx renderiza cada campo de fields.ts com
-- <AjudaCampo chave="ge.financiamento.<key>">. Esta migration semeia o texto das 56 chaves.
-- Aditiva, idempotente, sem tocar dado de cliente.
ON CONFLICT (chave) DO UPDATE SET
  rota = EXCLUDED.rota, grupo = EXCLUDED.grupo, rotulo = EXCLUDED.rotulo,
  o_que_preencher = EXCLUDED.o_que_preencher, para_que_serve = EXCLUDED.para_que_serve,
  exemplo = EXCLUDED.exemplo, erro_comum = EXCLUDED.erro_comum,
  vertical = EXCLUDED.vertical, ordem = EXCLUDED.ordem, atualizado_em = now();
